/** Shared data model. These shapes travel over the wire and into Postgres. */

export type Tool =
  | "select"
  | "pen"
  | "rect"
  | "ellipse"
  | "arrow"
  | "text"
  | "eraser"
  | "hand";

interface Base {
  /** Globally unique id, generated by the client that creates the element. */
  id: string;
  /** Millisecond timestamp of the last edit; last writer wins. */
  ts: number;
  /** Creation time, used only for stacking order. */
  z: number;
  /** Tombstone: the element was erased. */
  deleted?: boolean;
  /** Position of the element's origin in board coordinates. */
  x: number;
  y: number;
  color: string;
}

export interface PenElement extends Base {
  type: "pen";
  /** Flat [x0,y0,x1,y1,...] relative to (x,y). */
  points: number[];
  width: number;
}

export interface RectElement extends Base {
  type: "rect";
  w: number;
  h: number;
  width: number;
}

export interface EllipseElement extends Base {
  type: "ellipse";
  w: number;
  h: number;
  width: number;
}

export interface ArrowElement extends Base {
  type: "arrow";
  /** [x0,y0,x1,y1] relative to (x,y). */
  points: number[];
  width: number;
}

export interface TextElement extends Base {
  type: "text";
  text: string;
  size: number;
}

export type BoardElement =
  | PenElement
  | RectElement
  | EllipseElement
  | ArrowElement
  | TextElement;

/** What the server sends for an erased element. */
export interface Tombstone {
  id: string;
  ts: number;
  deleted: true;
}

/** Anything that can appear in an op: a full element or a tombstone. */
export type WireElement = BoardElement | Tombstone;

export interface Peer {
  id: string;
  name: string;
  color: string;
}

/** One undoable edit of one element. `undefined` means "does not exist". */
export interface Change {
  id: string;
  before: BoardElement | undefined;
  after: BoardElement | undefined;
}

export type ConnectionStatus = "connecting" | "live" | "reconnecting" | "offline";
